def restore_deque_positional_emplace_history(source):
    """Remove only the exact authenticated priority layer for historical checks."""
    digest = hashlib.sha256(source).hexdigest()
    assert digest in {R19_DEQUE_POSITIONAL_EMPLACE_REGISTERED_SHA256,R19_DEQUE_POSITIONAL_EMPLACE_MAINTAINED_SHA256}
    assert source.count(_R19_DEQUE_POSITIONAL_EMPLACE_ADDITIONS) == 1
    restored = source.replace(_R19_DEQUE_POSITIONAL_EMPLACE_ADDITIONS,b'',1)
    expected = (R19_DEQUE_POSITIONAL_EMPLACE_PREVIOUS_REGISTERED_SHA256 if digest == R19_DEQUE_POSITIONAL_EMPLACE_REGISTERED_SHA256
                else R19_DEQUE_POSITIONAL_EMPLACE_PREVIOUS_MAINTAINED_SHA256)
    assert hashlib.sha256(restored).hexdigest() == expected
    return restored


