def restore_list_value_history(source):
    """Remove only the exact authenticated priority layer for historical checks."""
    digest = hashlib.sha256(source).hexdigest()
    assert digest in {R19_LIST_VALUE_REGISTERED_SHA256,R19_LIST_VALUE_MAINTAINED_SHA256}
    assert source.count(_R19_LIST_VALUE_ADDITIONS) == 1
    restored = source.replace(_R19_LIST_VALUE_ADDITIONS,b'',1)
    expected = (R19_LIST_VALUE_PREVIOUS_REGISTERED_SHA256 if digest == R19_LIST_VALUE_REGISTERED_SHA256
                else R19_LIST_VALUE_PREVIOUS_MAINTAINED_SHA256)
    assert hashlib.sha256(restored).hexdigest() == expected
    return restored


