def restore_bitset_text_hash_swap_history(source):
    """Remove only the exact authenticated priority layer for historical checks."""
    digest = hashlib.sha256(source).hexdigest()
    assert digest in {R19_BITSET_TEXT_HASH_SWAP_REGISTERED_SHA256,R19_BITSET_TEXT_HASH_SWAP_MAINTAINED_SHA256}
    assert source.count(_R19_BITSET_TEXT_HASH_SWAP_ADDITIONS) == 1
    restored = source.replace(_R19_BITSET_TEXT_HASH_SWAP_ADDITIONS,b'',1)
    expected = (R19_BITSET_TEXT_HASH_SWAP_PREVIOUS_REGISTERED_SHA256 if digest == R19_BITSET_TEXT_HASH_SWAP_REGISTERED_SHA256
                else R19_BITSET_TEXT_HASH_SWAP_PREVIOUS_MAINTAINED_SHA256)
    assert hashlib.sha256(restored).hexdigest() == expected
    return restored


